#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

typedef struct {
    long long x1, y1, x2, y2;
} Rect;

static inline long long dist_rect(const Rect *a, const Rect *b) {
    long long dx = 0;
    if (a->x2 < b->x1) {
        dx = b->x1 - a->x2;
    } else if (b->x2 < a->x1) {
        dx = a->x1 - b->x2;
    }

    long long dy = 0;
    if (a->y2 < b->y1) {
        dy = b->y1 - a->y2;
    } else if (b->y2 < a->y1) {
        dy = a->y1 - b->y2;
    }

    return dx + dy;
}

int main(void) {
    long long xi, yi, xf, yf;
    if (scanf("%lld %lld %lld %lld", &xi, &yi, &xf, &yf) != 4) {
        return 0;
    }

    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int total_nodes = n + 2;
    Rect *rects = (Rect *)malloc(total_nodes * sizeof(Rect));
    if (!rects) return 0;

    for (int i = 0; i < n; i++) {
        long long x1, y1, x2, y2;
        scanf("%lld %lld %lld %lld", &x1, &y1, &x2, &y2);
        if (x1 > x2) { long long t = x1; x1 = x2; x2 = t; }
        if (y1 > y2) { long long t = y1; y1 = y2; y2 = t; }
        rects[i].x1 = x1;
        rects[i].y1 = y1;
        rects[i].x2 = x2;
        rects[i].y2 = y2;
    }

    int start_node = n;
    int end_node = n + 1;

    rects[start_node].x1 = rects[start_node].x2 = xi;
    rects[start_node].y1 = rects[start_node].y2 = yi;

    rects[end_node].x1 = rects[end_node].x2 = xf;
    rects[end_node].y1 = rects[end_node].y2 = yf;

    long long *dist = (long long *)malloc(total_nodes * sizeof(long long));
    bool *visited = (bool *)calloc(total_nodes, sizeof(bool));

    for (int i = 0; i < total_nodes; i++) {
        dist[i] = INF;
    }
    dist[start_node] = 0;

    for (int i = 0; i < total_nodes; i++) {
        int u = -1;
        long long min_d = INF;

        for (int v = 0; v < total_nodes; v++) {
            if (!visited[v] && dist[v] < min_d) {
                min_d = dist[v];
                u = v;
            }
        }

        if (u == -1 || u == end_node) {
            break;
        }

        visited[u] = true;

        for (int v = 0; v < total_nodes; v++) {
            if (!visited[v]) {
                long long weight = dist_rect(&rects[u], &rects[v]);
                if (dist[u] + weight < dist[v]) {
                    dist[v] = dist[u] + weight;
                }
            }
        }
    }

    printf("%lld\n", dist[end_node]);

    free(rects);
    free(dist);
    free(visited);

    return 0;
}
```

